package com.hbm.machine.radiolysis;
import com.hbm.fluid.*;import com.hbm.recipe.cracking.CrackingRecipes;import com.hbm.recipe.generic.GenericRecipeData;import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.MinecraftServer;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.*;import net.neoforged.bus.api.EventPriority;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.OnDatapackSyncEvent;import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Original water recipe followed by every actual shared cracking recipe, synchronized through native recipes. */
public final class RadiolysisRecipeConfig {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();
 public static void register(){NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent event)->install(event.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent event)->{var server=event.getPlayerList().getServer();if(event.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<RadiolysisRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(RadiolysisContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(recipe->recipe.data().order())).toList();}
 public static RadiolysisRecipe find(RecipeManager manager,HbmFluidType input){return recipes(manager).stream().filter(recipe->recipe.data().inputFluids().getFirst().type==input).findFirst().orElse(null);}
 private static void install(MinecraftServer server){var source=CrackingRecipes.load();if(source.isEmpty())throw new IllegalStateException("CrackingRecipes.getCrackingRecipes has yielded an empty map while registering the radiolysis recipes! Either the load order is broken or cracking recipes have been removed!");var map=new LinkedHashMap<HbmFluidType,CrackingRecipes.Entry>();map.put(HbmFluids.WATER,new CrackingRecipes.Entry(HbmFluids.WATER,new FluidStack(HbmFluids.PEROXIDE,80),new FluidStack(HbmFluids.HYDROGEN,20)));for(var entry:source)map.put(entry.input(),entry);var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();int order=0;for(var row:map.values()){var data=new GenericRecipeData("radiolysis."+row.input().getName(),0,0,List.of(),List.of(new FluidStack(row.input(),100)),List.of(),List.of(row.left(),row.right()),List.of(),"",ItemStack.EMPTY,false,"",order++);var id=RadiolysisContent.id("radiolysis/"+row.input().getName().toLowerCase(Locale.ROOT));additions.put(id,new RecipeHolder<>(id,new RadiolysisRecipe(data)));}additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);}
 private RadiolysisRecipeConfig(){}
}
